/**
 * buffers.ts — GPU 버퍼 할당, 읽기, Zero-Copy 인터페이스
 *
 * C-05 Fix: _stagingBuffers 전역 Map 제거.
 *   기존에는 전역 Map에 (computeBuffer → stagingBuffer)를 저장하여
 *   두 텐서를 동시에 readback 시 순서가 뒤바뀌면 데이터 오염이 발생했다.
 *   → 이제 mapBufferAsync가 staging buffer를 반환하고
 *     readMappedInto가 그 staging buffer를 직접 인자로 받는다.
 *     handle 기반 래퍼(gpuCore.ts)에서 핸들별로 staging buffer를 관리.
 *
 * H-05 Fix: ensureFloat32Array의 불필요한 deep copy 제거 (진짜 Zero-Copy).
 */

import { getDevice, getQueue } from "./device";
import { _globalQuotaManager } from "./quota";

export function allocateBuffer(byteLength: number, usage: GPUBufferUsageFlags): GPUBuffer {
  _globalQuotaManager.reserve(byteLength);
  try {
    return getDevice().createBuffer({ size: byteLength, usage });
  } catch (e) {
    _globalQuotaManager.release(byteLength);
    throw e;
  }
}

export function writeFloat32Array(buffer: GPUBuffer, data: Float32Array): void {
  getQueue().writeBuffer(buffer, 0, data.buffer, data.byteOffset, data.byteLength);
}

/** 전통적인 full-copy readback (readBufferToFloat32Array에서만 사용) */
export async function readBufferToFloat32Array(
  buffer: GPUBuffer,
  byteLength: number
): Promise<Float32Array> {
  const device = getDevice();
  const stagingBuffer = device.createBuffer({
    size: byteLength,
    usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
  });

  try {
    const commandEncoder = device.createCommandEncoder();
    commandEncoder.copyBufferToBuffer(buffer, 0, stagingBuffer, 0, byteLength);
    device.queue.submit([commandEncoder.finish()]);
    await stagingBuffer.mapAsync(GPUMapMode.READ);

    try {
      const arrayBuffer = stagingBuffer.getMappedRange();
      return new Float32Array(arrayBuffer.slice(0));
    } finally {
      stagingBuffer.unmap();
    }
  } finally {
    stagingBuffer.destroy();
  }
}

/**
 * C-05 Fix: mapBufferAsync는 staging buffer를 직접 반환한다.
 * 전역 Map 없이 호출자가 staging buffer 참조를 들고 있어 동시 readback 안전.
 */
export async function mapBufferAsync(
  buffer: GPUBuffer,
  byteLength: number
): Promise<GPUBuffer> {
  const device = getDevice();
  const stagingBuffer = device.createBuffer({
    size: byteLength,
    usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
  });

  const commandEncoder = device.createCommandEncoder();
  commandEncoder.copyBufferToBuffer(buffer, 0, stagingBuffer, 0, byteLength);
  device.queue.submit([commandEncoder.finish()]);

  // GPU 연산 완료 + 메모리 맵핑 완료까지 대기
  await stagingBuffer.mapAsync(GPUMapMode.READ);
  return stagingBuffer;
}

/**
 * C-05 Fix: staging buffer를 인자로 받아 Zero-Copy 읽기 수행.
 * H-05 Fix: outArray.set()이 이미 직접 쓰기 — new Float32Array() 중간 복사 없음.
 */
export function readMappedInto(
  stagingBuffer: GPUBuffer,
  outArray: Float32Array
): void {
  try {
    const arrayBuffer = stagingBuffer.getMappedRange();
    // 직접 WASM 힙 뷰에 쓰기 (Zero-Copy)
    outArray.set(new Float32Array(arrayBuffer));
  } finally {
    stagingBuffer.unmap();
    stagingBuffer.destroy();
  }
}

export function freeBuffer(buffer: GPUBuffer, byteLength: number): void {
  _globalQuotaManager.release(byteLength);
  buffer.destroy();
}
